export type CitationScope = '经文' | '解读' | '背景' | '串联' | '应用';

export type StudyCitation = {
  id: string;
  label: string;
  url: string;
  scope: CitationScope;
};

export type VerseInsight = {
  range: string;
  direct: string;
  depth: string;
};

export type InterpretationNote = {
  title: string;
  text: string;
};

export type StudyNote = {
  range: string;
  title: string;
  scripture: string;
  scene: string;
  literal: string;
  context: string;
  connection?: string;
  life?: string;
  citations?: StudyCitation[];
  verseInsights?: VerseInsight[];
  interpretationNotes?: InterpretationNote[];
};

